-- =============================================================================
-- Meridian Core Banking Platform
-- Migration 001: Core schema (customers, accounts, transactions, audit_logs,
--                 api_users)
--
-- Engine: PostgreSQL 16 (Amazon RDS)
--
-- Design notes:
--   - All primary keys are UUIDs (gen_random_uuid()), generated by the
--     database rather than the application, so IDs are safe to expose in
--     the API without leaking sequential ordering/volume information.
--   - Money is always NUMERIC(19,4) — never FLOAT/DOUBLE — to avoid
--     floating point rounding errors on financial amounts.
--   - Every money-bearing/identity table has created_at (and updated_at
--     where rows are mutable) for auditability.
--   - Foreign keys use ON DELETE RESTRICT throughout: a bank should never
--     be able to accidentally cascade-delete a customer's transaction
--     history. Deactivation is modeled via a `status` column, not row
--     deletion.
-- =============================================================================

-- pgcrypto provides gen_random_uuid(); this is the standard, actively
-- maintained extension for UUID generation on PostgreSQL 13+ (uuid-ossp is
-- the older alternative and is not required here).
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- -----------------------------------------------------------------------------
-- Table: customers
-- -----------------------------------------------------------------------------
CREATE TABLE customers (
    customer_id       UUID            PRIMARY KEY DEFAULT gen_random_uuid(),
    first_name        VARCHAR(100)    NOT NULL,
    last_name         VARCHAR(100)    NOT NULL,
    email             VARCHAR(255)    NOT NULL,
    phone_number      VARCHAR(20),
    date_of_birth     DATE            NOT NULL,
    address_line1     VARCHAR(255),
    address_line2     VARCHAR(255),
    city              VARCHAR(100),
    state_province    VARCHAR(100),
    postal_code       VARCHAR(20),
    country           VARCHAR(100),
    -- Never store a raw national ID / SSN. The application layer hashes it
    -- (e.g., HMAC-SHA256 with a server-side secret) before it ever reaches
    -- this column, so this table alone is never sufficient to identify a
    -- person by government ID even in a breach scenario.
    national_id_hash  VARCHAR(255),
    status            VARCHAR(20)     NOT NULL DEFAULT 'ACTIVE',
    created_at        TIMESTAMPTZ     NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ     NOT NULL DEFAULT now(),

    CONSTRAINT uq_customers_email UNIQUE (email),
    CONSTRAINT chk_customers_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')),
    CONSTRAINT chk_customers_dob_past CHECK (date_of_birth < CURRENT_DATE)
);

COMMENT ON TABLE customers IS 'Retail bank customers. One row per natural person or business entity.';
COMMENT ON COLUMN customers.national_id_hash IS 'Application-computed hash of a government ID; raw ID is never persisted.';

-- Search patterns: "search customers" by name, and lookups by email/status.
CREATE INDEX idx_customers_last_first_name ON customers (last_name, first_name);
CREATE INDEX idx_customers_status ON customers (status);
-- Supports fast, case-insensitive partial-name search from the frontend
-- search box (used with ILIKE '%term%').
CREATE INDEX idx_customers_name_trgm_ready ON customers (lower(first_name), lower(last_name));


-- -----------------------------------------------------------------------------
-- Table: accounts
-- -----------------------------------------------------------------------------
CREATE TABLE accounts (
    account_id        UUID            PRIMARY KEY DEFAULT gen_random_uuid(),
    -- Human-facing account number, distinct from the internal UUID PK.
    -- Generated by the application (see backend service layer) using a
    -- checksum-friendly format, e.g. "MER-0000001234".
    account_number    VARCHAR(20)     NOT NULL,
    customer_id       UUID            NOT NULL,
    account_type      VARCHAR(20)     NOT NULL,
    currency_code     CHAR(3)         NOT NULL DEFAULT 'USD',
    balance           NUMERIC(19,4)   NOT NULL DEFAULT 0,
    status            VARCHAR(20)     NOT NULL DEFAULT 'ACTIVE',
    created_at        TIMESTAMPTZ     NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ     NOT NULL DEFAULT now(),

    CONSTRAINT uq_accounts_account_number UNIQUE (account_number),
    CONSTRAINT fk_accounts_customer
        FOREIGN KEY (customer_id) REFERENCES customers (customer_id)
        ON DELETE RESTRICT,
    CONSTRAINT chk_accounts_type CHECK (account_type IN ('CHECKING', 'SAVINGS')),
    CONSTRAINT chk_accounts_status CHECK (status IN ('ACTIVE', 'FROZEN', 'CLOSED')),
    -- The single most important constraint in this schema: the database
    -- itself refuses to ever let a balance go negative, even if application
    -- logic has a bug. Overdraft products, if ever added, would need an
    -- explicit, separate design (e.g. a credit_limit column) rather than
    -- relaxing this.
    CONSTRAINT chk_accounts_balance_non_negative CHECK (balance >= 0)
);

COMMENT ON TABLE accounts IS 'Bank accounts owned by a customer. Balance is authoritative and denormalized here for fast reads; transactions table is the append-only source of truth for how it got there.';

CREATE INDEX idx_accounts_customer_id ON accounts (customer_id);
CREATE INDEX idx_accounts_status ON accounts (status);
-- Supports "search accounts" by account number prefix from the frontend.
CREATE INDEX idx_accounts_account_number ON accounts (account_number);


-- -----------------------------------------------------------------------------
-- Table: transactions
-- -----------------------------------------------------------------------------
CREATE TABLE transactions (
    transaction_id      UUID            PRIMARY KEY DEFAULT gen_random_uuid(),
    account_id           UUID            NOT NULL,
    -- Populated only for TRANSFER_IN / TRANSFER_OUT rows: the account on
    -- the other side of the transfer. NULL for DEPOSIT / WITHDRAWAL.
    related_account_id   UUID,
    transaction_type      VARCHAR(20)     NOT NULL,
    amount                 NUMERIC(19,4)   NOT NULL,
    -- The account's balance immediately AFTER this transaction was applied.
    -- Denormalized on purpose: it turns "show transaction history" into a
    -- single indexed read instead of a running-balance recomputation over
    -- the full history for every request.
    balance_after           NUMERIC(19,4)   NOT NULL,
    description               VARCHAR(255),
    status                     VARCHAR(20)     NOT NULL DEFAULT 'COMPLETED',
    -- Links the TRANSFER_OUT row on the source account with the
    -- TRANSFER_IN row on the destination account, so a single transfer
    -- request is always exactly two transaction rows sharing one group id.
    transfer_group_id          UUID,
    created_at                  TIMESTAMPTZ     NOT NULL DEFAULT now(),

    CONSTRAINT fk_transactions_account
        FOREIGN KEY (account_id) REFERENCES accounts (account_id)
        ON DELETE RESTRICT,
    CONSTRAINT fk_transactions_related_account
        FOREIGN KEY (related_account_id) REFERENCES accounts (account_id)
        ON DELETE RESTRICT,
    CONSTRAINT chk_transactions_type
        CHECK (transaction_type IN ('DEPOSIT', 'WITHDRAWAL', 'TRANSFER_IN', 'TRANSFER_OUT')),
    CONSTRAINT chk_transactions_status
        CHECK (status IN ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED')),
    CONSTRAINT chk_transactions_amount_positive CHECK (amount > 0),
    CONSTRAINT chk_transactions_balance_after_non_negative CHECK (balance_after >= 0),
    -- Transfer rows must carry a related_account_id and a transfer_group_id;
    -- deposit/withdrawal rows must not.
    CONSTRAINT chk_transactions_transfer_fields CHECK (
        (transaction_type IN ('TRANSFER_IN', 'TRANSFER_OUT')
            AND related_account_id IS NOT NULL
            AND transfer_group_id IS NOT NULL)
        OR
        (transaction_type IN ('DEPOSIT', 'WITHDRAWAL')
            AND related_account_id IS NULL)
    )
);

COMMENT ON TABLE transactions IS 'Append-only ledger of every money movement. Rows are never updated or deleted by the application; corrections are modeled as new REVERSED-linked entries, not mutation.';

-- The dominant read pattern is "give me this account's history, most
-- recent first" — this composite index serves that directly.
CREATE INDEX idx_transactions_account_created ON transactions (account_id, created_at DESC);
CREATE INDEX idx_transactions_transfer_group ON transactions (transfer_group_id) WHERE transfer_group_id IS NOT NULL;
CREATE INDEX idx_transactions_type ON transactions (transaction_type);
-- Supports "view recent transactions" (system-wide) and dashboard queries.
CREATE INDEX idx_transactions_created_at ON transactions (created_at DESC);


-- -----------------------------------------------------------------------------
-- Table: audit_logs
-- -----------------------------------------------------------------------------
CREATE TABLE audit_logs (
    audit_id       BIGSERIAL       PRIMARY KEY,
    entity_type    VARCHAR(50)     NOT NULL,
    entity_id      UUID            NOT NULL,
    action         VARCHAR(20)     NOT NULL,
    -- 'system' for trigger-generated rows where no authenticated user is
    -- in context (e.g. migrations/seed data); otherwise the api_users
    -- username or 'customer:<id>' for self-service actions.
    performed_by   VARCHAR(100)    NOT NULL DEFAULT 'system',
    old_value      JSONB,
    new_value      JSONB,
    ip_address     VARCHAR(45),
    created_at     TIMESTAMPTZ     NOT NULL DEFAULT now(),

    CONSTRAINT chk_audit_logs_action CHECK (action IN ('INSERT', 'UPDATE', 'DELETE'))
);

COMMENT ON TABLE audit_logs IS 'Immutable audit trail. Populated primarily by database triggers (see migration 002) so it cannot be bypassed by application code that forgets to log something.';

CREATE INDEX idx_audit_logs_entity ON audit_logs (entity_type, entity_id);
CREATE INDEX idx_audit_logs_created_at ON audit_logs (created_at DESC);


-- -----------------------------------------------------------------------------
-- Table: api_users
-- Staff/service accounts that authenticate to the REST API (tellers,
-- admins). Distinct from `customers`, who are the bank's clients and are
-- not modeled as API principals in this project.
-- -----------------------------------------------------------------------------
CREATE TABLE api_users (
    user_id         UUID            PRIMARY KEY DEFAULT gen_random_uuid(),
    username        VARCHAR(50)     NOT NULL,
    -- bcrypt hash, never a plaintext password. See backend auth service.
    password_hash   VARCHAR(255)    NOT NULL,
    role            VARCHAR(20)     NOT NULL DEFAULT 'TELLER',
    is_active       BOOLEAN         NOT NULL DEFAULT true,
    created_at      TIMESTAMPTZ     NOT NULL DEFAULT now(),
    last_login_at   TIMESTAMPTZ,

    CONSTRAINT uq_api_users_username UNIQUE (username),
    CONSTRAINT chk_api_users_role CHECK (role IN ('ADMIN', 'TELLER', 'VIEWER'))
);

COMMENT ON TABLE api_users IS 'Staff accounts authenticating to the API. Intentionally excluded from the generic audit trigger (migration 002) so password_hash values never get written into audit_logs.old_value/new_value.';

CREATE INDEX idx_api_users_username ON api_users (username);
